public class MerfitScoreConfiguration : IEntityTypeConfiguration<MerfitScore>
{
    /// <summary>
    /// MerfitScore varligi icin tablo adi, birincil anahtar, alan kisitlari ve iliskileri yapilandirir.
    /// </summary>
