    {
        // Tablo adini belirtir.
        builder.ToTable("MerfitScore", "gamification");

        // Birincil anahtari tanimlar.
        builder.HasKey(x => x.Id);

        // Hesaplanan toplam skor degeri.
        builder.Property(x => x.Score)
